package com.autoops.execution.controller;import com.autoops.execution.entity.Execution;import com.autoops.execution.service.ExecutionService;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController @RequestMapping("/api/executions")public class ExecutionController{private final ExecutionService service;public ExecutionController(ExecutionService s){service=s;}public record CommandRun(Long commandId,List<Long> machineIds,String mode,Integer concurrency){}@PostMapping("/commands")public Execution run(@RequestBody CommandRun r){return service.createCommand(1L,r.commandId(),r.machineIds(),r.mode()==null?"MANUAL":r.mode(),r.concurrency()==null?1:r.concurrency());}@GetMapping public List<Execution> history(){return service.history(1L);}}
